const FMD = {"title":"Daily Scripture Formation","lead":"What occupies your mind shapes how you live.","intro":"Scripture calls us to renew our minds, guard our hearts, and put God’s Word into practice. Begin the morning with truth, return to it during the day, and end the evening in reflection.","motto":"Read. Meditate. Examine. Obey.","found":[{"l":"Romans 12:2","r":[58,12,2,2],"tr":"Berean Literal Bible"},{"l":"Psalm 1:1–3","r":[28,1,1,3],"tr":"Septuagint"},{"l":"Proverbs 4:23","r":[29,4,23,23],"tr":"Septuagint"},{"l":"Philippians 4:8","r":[63,4,8,8],"tr":"Berean Literal Bible"},{"l":"Hebrews 5:14","r":[71,5,14,14],"tr":"Berean Literal Bible"},{"l":"James 1:22","r":[77,1,22,22],"tr":"Berean Literal Bible"}],"ses":[{"id":"morning","label":"Morning","name":"Establish","minutes":"10–15 minutes","purpose":"Begin the day with Scripture before social media and other distractions: renew the mind, seek wisdom and discernment, and set the day’s intentions."},{"id":"afternoon","label":"Afternoon","name":"Correct","minutes":"5–10 minutes","purpose":"Pause during the day to examine your conduct, resist temptation, practise self-control, and bring your actions back in line with Scripture."},{"id":"evening","label":"Evening","name":"Examine","minutes":"5–10 minutes","purpose":"End the day in reflection, repentance, gratitude, humility, and trust in God."}],"cur":"first-cycle","cy":[{"id":"first-cycle","title":"The first cycle","days":[{"t":"Renewing the Mind","s":[{"refs":[{"l":"Romans 12:1–3","r":[58,12,1,3],"tr":"Berean Literal Bible"},{"l":"Psalm 1","r":[28,1,0,0],"tr":"Septuagint"}],"do":"Before you open a screen, offer the day to God. Name one way of thinking this age has pressed on you, and decide what your mind will dwell on instead."},{"refs":[{"l":"Philippians 4:4–9","r":[63,4,4,9],"tr":"Berean Literal Bible"}],"do":"Stop and look at what has filled your mind since morning. Measure it against the things Paul tells you to think on, and set aside one thing that does not belong."},{"refs":[{"l":"Psalm 4","r":[28,4,0,0],"tr":"Septuagint"}],"do":"Lie down in quiet and search your heart. What did you say in your heart today that you need to bring to the Lord?"}]},{"t":"Guarding Attention","s":[{"refs":[{"l":"Proverbs 4:20–27","r":[29,4,20,27],"tr":"Septuagint"}],"do":"Decide now what your eyes and ears will not take in today, and where your feet will not go. Keep to it."},{"refs":[{"l":"Matthew 6:19–24","r":[53,6,19,24],"tr":"Berean Literal Bible"}],"do":"Where has your attention gone since morning? Ask which master it served, and turn it back."},{"refs":[{"l":"Psalm 100","r":[28,100,0,0],"tr":"Septuagint","en":"Psalm 101 in English Bibles"}],"do":"Review what you set before your eyes today. Name one thing you will not set before them tomorrow."}]},{"t":"Self-Control","s":[{"refs":[{"l":"Proverbs 25:28","r":[29,25,28,28],"tr":"Septuagint"},{"l":"Galatians 5:16–25","r":[61,5,16,25],"tr":"Berean Literal Bible"}],"do":"Name the desire most likely to rule you today. Before you act on it, stop, seek counsel, and ask what walking by the Spirit would look like."},{"refs":[{"l":"1 Corinthians 9:24–27","r":[59,9,24,27],"tr":"Berean Literal Bible"}],"do":"Choose one small act of discipline this afternoon, and keep it without telling anyone."},{"refs":[{"l":"Psalm 50","r":[28,50,0,0],"tr":"Septuagint","en":"Psalm 51 in English Bibles"}],"do":"Where did you give way today? Confess it plainly to God, without excuse, and ask Him for a clean heart."}]},{"t":"Wisdom and Discernment","s":[{"refs":[{"l":"Proverbs 2","r":[29,2,0,0],"tr":"Septuagint"}],"do":"Ask God for wisdom before the day’s first decision, and seek it as you would search for treasure."},{"refs":[{"l":"James 1:5–8","r":[77,1,5,8],"tr":"Berean Literal Bible"},{"l":"James 1:19–27","r":[77,1,19,27],"tr":"Berean Literal Bible"}],"do":"In your next conversation, be quick to hear and slow to speak. Then do one thing the word asks of you, not only hear it."},{"refs":[{"l":"Psalm 138:23–24","r":[28,138,23,24],"tr":"Septuagint","en":"Psalm 139:23–24 in English Bibles"}],"do":"Ask God to search you and to show you any way of iniquity in you. Write down what comes to mind, and bring it to Him."}]},{"t":"Courage and Faithfulness","s":[{"refs":[{"l":"Daniel 3","r":[38,3,0,0],"tr":"Septuagint"}],"do":"Name the place where you are pressed to bow today. Decide now that you will not, whatever it costs."},{"refs":[{"l":"Acts 4:13–22","r":[57,4,13,22],"tr":"Berean Literal Bible"}],"do":"Where are you tempted to stay silent about Christ? Speak plainly once today, with courage and respect."},{"refs":[{"l":"Psalm 26","r":[28,26,0,0],"tr":"Septuagint","en":"Psalm 27 in English Bibles"}],"do":"What did you fear today? Bring it to the Lord, your light, and wait on Him."}]},{"t":"Humility and Correction","s":[{"refs":[{"l":"Sirach 3:17–31","r":[51,3,17,31],"tr":"Septuagint"}],"do":"Do your work today in meekness. Where you are greater, humble yourself the more."},{"refs":[{"l":"Matthew 18:1–4","r":[53,18,1,4],"tr":"Berean Literal Bible"}],"do":"Where are you seeking to be great today? Take the lower place in one conversation or task."},{"refs":[{"l":"Psalm 130","r":[28,130,0,0],"tr":"Septuagint","en":"Psalm 131 in English Bibles"}],"do":"Lay down one ambition or worry that is too great for you, and quiet your soul before the Lord."}]},{"t":"Love, Obedience, and Sabbath Reflection","s":[{"refs":[{"l":"Matthew 5:1–16","r":[53,5,1,16],"tr":"Berean Literal Bible"}],"do":"Read the Beatitudes slowly. Which one is furthest from your life? Ask God to form it in you."},{"refs":[{"l":"1 Corinthians 13","r":[59,13,0,0],"tr":"Berean Literal Bible"}],"do":"Measure the week’s words and actions against love as Paul describes it. Where did you fall short, and whom will you seek to make it right with?"},{"refs":[{"l":"John 15:1–17","r":[56,15,1,17],"tr":"Berean Literal Bible"}],"do":"Rest in Christ, the vine. Look back over the week: what fruit has obedience borne, and where must you abide more closely?"}]}]}]};
